// Constraint: prose values come from the sources, never typed into the generator.
import { test } from "node:test";
import assert from "node:assert/strict";
import { cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const FILES = ["scripts/gen-design-md.mjs", "sondalab.tokens.json", "packages/ui-kit/neutrals.json",
  "packages/ui-kit/agent/accent-registry.json", "docs/design-language.md", "packages/ui-kit/agent/flavour.md"];

test("a changed prose value is followed or rejected, never left stale", async () => {
  const dir = mkdtempSync(join(tmpdir(), "dm-"));
  try {
    for (const f of FILES) {
      mkdirSync(dirname(join(dir, f)), { recursive: true });
      cpSync(join(REPO, f), join(dir, f));
    }
    for (const f of ["docs/design-language.md", "packages/ui-kit/agent/flavour.md"]) {
      const p = join(dir, f);
      writeFileSync(p, readFileSync(p, "utf8").replaceAll("8x8", "4x4"));
    }
    const { buildDesignMd } = await import(pathToFileURL(join(dir, FILES[0])).href);
    let out;
    try { out = buildDesignMd(); } catch { return; }
    assert.ok(!out.includes("8x8"), "DESIGN.md still says 8x8 although no source does: the value is typed into the generator");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

// Constraint: missing source content makes the generator fail, never write an empty value.
import { test } from "node:test";
import assert from "node:assert/strict";
import { cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const FILES = ["scripts/gen-design-md.mjs", "sondalab.tokens.json", "packages/ui-kit/neutrals.json",
  "packages/ui-kit/agent/accent-registry.json", "docs/design-language.md", "packages/ui-kit/agent/flavour.md"];

test("an empty product accent makes buildDesignMd fail", async () => {
  const dir = mkdtempSync(join(tmpdir(), "dm-"));
  try {
    for (const f of FILES) {
      mkdirSync(dirname(join(dir, f)), { recursive: true });
      cpSync(join(REPO, f), join(dir, f));
    }
    const p = join(dir, "packages/ui-kit/agent/accent-registry.json");
    const reg = JSON.parse(readFileSync(p, "utf8"));
    reg.products.introspect.light = "";
    writeFileSync(p, JSON.stringify(reg));
    const { buildDesignMd } = await import(pathToFileURL(join(dir, FILES[0])).href);
    assert.throws(() => buildDesignMd(), "an empty accent was written into DESIGN.md without an error");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

// Constraint: never write a stale value; the bezel card status comes from flavour.md.
import { test } from "node:test";
import assert from "node:assert/strict";
import { cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const FILES = ["scripts/gen-design-md.mjs", "sondalab.tokens.json", "packages/ui-kit/neutrals.json",
  "packages/ui-kit/agent/accent-registry.json", "docs/design-language.md", "packages/ui-kit/agent/flavour.md"];

test("a shipped bezel card is not still described as not shipped", async () => {
  const dir = mkdtempSync(join(tmpdir(), "dm-"));
  try {
    for (const f of FILES) {
      mkdirSync(dirname(join(dir, f)), { recursive: true });
      cpSync(join(REPO, f), join(dir, f));
    }
    const p = join(dir, "packages/ui-kit/agent/flavour.md");
    writeFileSync(p, readFileSync(p, "utf8")
      .replace("(chosen, not yet shipped)", "(shipped)")
      .replace(/It is not in `components\.css`[^\n]*/, "It ships in `components.css` and `catalog.md`."));
    const { buildDesignMd } = await import(pathToFileURL(join(dir, FILES[0])).href);
    let out;
    try { out = buildDesignMd(); } catch { return; }
    assert.doesNotMatch(out, /not yet shipped/, "stale bezel card status written");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

