import test from "node:test";
import assert from "node:assert/strict";
import { buildDesignMd } from "./gen-design-md.mjs";

// Requirement: design-language.md wins. The accent fill token is not the ink of
// the focus ring, links or tag text; those take the capped accent-text reading.
test("--sl-accent-default is not given as the focus ring, link or tag ink", () => {
  const row = buildDesignMd()
    .split("\n")
    .find((l) => l.startsWith("| `--sl-accent-default` |"));
  assert.ok(row, "accent-default row is missing");
  const purpose = row.split("|").at(-2);
  assert.doesNotMatch(purpose, /focus ring|links|tags/i);
});

